ALTER TABLE public.programmes
  ADD COLUMN IF NOT EXISTS tagline text,
  ADD COLUMN IF NOT EXISTS session_label text,
  ADD COLUMN IF NOT EXISTS intro text,
  ADD COLUMN IF NOT EXISTS sections jsonb NOT NULL DEFAULT '[]'::jsonb,
  ADD COLUMN IF NOT EXISTS trial_countries text[] NOT NULL DEFAULT '{}'::text[],
  ADD COLUMN IF NOT EXISTS note text,
  ADD COLUMN IF NOT EXISTS non_refundable boolean NOT NULL DEFAULT true,
  ADD COLUMN IF NOT EXISTS cta_title text,
  ADD COLUMN IF NOT EXISTS cta_body text,
  ADD COLUMN IF NOT EXISTS cta_label text,
  ADD COLUMN IF NOT EXISTS is_published boolean NOT NULL DEFAULT true,
  ADD COLUMN IF NOT EXISTS display_order integer NOT NULL DEFAULT 0;

GRANT SELECT ON public.programmes TO anon;
GRANT SELECT, INSERT, UPDATE, DELETE ON public.programmes TO authenticated;
GRANT ALL ON public.programmes TO service_role;

DROP POLICY IF EXISTS "Public read programmes" ON public.programmes;
CREATE POLICY "Public read published programmes" ON public.programmes FOR SELECT TO anon, authenticated USING (is_published OR public.is_staff(auth.uid()));

INSERT INTO public.programmes (slug, name, tagline, age_range, session_label, fee_amount, fee_period, fee_confirmed, non_refundable, display_order, inclusions, intro, trial_countries, note, cta_title, cta_body, cta_label, sections) VALUES
('football-camping', '1-Month Football Camping', 'Fully residential pathway to professional football', 'Ages 12 – 22', '1 Month · Fully Residential', 450000, 'month', true, true, 1,
 ARRAY['Intensive daily training (tactical, technical)','Ball mastery, passing, shooting, movement','Fitness, endurance, agility, gym conditioning','Official training kits provided','International trials opportunities (UK, Spain, Italy)','24/7 supervision and mentorship'],
 'Are you a young footballer between the ages of 12 and 22 looking to take your talent to the next level? The Buruj One-Month Football & Camping Programme is an intensive residential experience combining top-tier football training, career-building exposure and a supportive environment for athletic and personal development — designed to identify and groom elite talent and open doors to national recognition and international trials.',
 ARRAY['United Kingdom','Spain','France','Italy','Portugal','Lithuania','Sweden'],
 'International trial opportunities are not guaranteed for all participants. Only outstanding players — based on performance, attitude and potential — may be considered. Terms and conditions apply.',
 'Ready to get started?', 'Enrollment for the 1-Month Football & Trials Programme is now open. Limited slots available — registration is competitive.', 'Join the camping programme',
 '[{"title":"Advanced Football Training","body":"Train in a professional-style environment under licensed, experienced coaches.","items":["Intensive training sessions daily (tactical, technical)","Ball mastery, passing, shooting, movement and decision-making","Fitness, endurance, agility and gym-based conditioning","Tactical and positional play","Small-sided games, match simulations and team-building exercises","Official training kits provided to all participants"]},{"title":"Selection Criteria","body":"Selection into Buruj Sports Academy Club and the NLO pathway team is strictly performance-based and assessed by the Technical Team.","items":["Technical proficiency (ball control, passing, shooting)","Tactical understanding and decision-making","Physical fitness, speed, strength and stamina","Discipline, coachability and overall attitude","Match performance and teamwork"]},{"title":"Residential Accommodation & Welfare","body":"Fully residential, providing a safe and focused environment.","items":["Clean and secure accommodation","24/7 supervision and mentorship","Nutritious daily meals tailored for athletes","Onsite medical support and medical insurance coverage","Access to fitness and recovery facilities","Recreational and social activities"]},{"title":"Who Should Apply?","body":"This programme is ideal for:","items":["Young footballers aged 12 to 22 looking to sharpen their skills","Grassroots players seeking elite training and career exposure","Students on holiday or break looking for structured development","Talents with ambition to play at national or international levels"]}]'::jsonb),
('football-education', 'Football & Education', 'Balance academics with athletic excellence', 'JSS 1 – SS 3', '2025/2026 Session', 5500000, 'session', true, true, 2,
 ARRAY['Integrated academic schedule (WAEC & NECO)','Professional football training','Educational support and tutoring','Scholarship opportunities','Pathway to higher education','Character development programmes'],
 'At Buruj Sports Academy we go beyond sport — we provide a complete environment for academic excellence, professional football training and total personal development. Designed for students from JSS 1 to SS 3, the programme nurtures young talent academically, athletically and morally.',
 ARRAY[]::text[], NULL,
 'Ready to enroll?', 'Join the Football & Education Programme for the 2025/2026 session and give yourself the best chance at academic and athletic excellence.', 'Enroll now',
 '[{"title":"Academic Excellence: JSS 1 to SS 3","body":"Our structured programme follows the Nigerian curriculum and prepares students for WAEC, NECO and other important exams.","items":["Qualified teachers for all core and elective subjects","Classes held in the morning before training","Academic textbooks and learning materials provided","Small class sizes and personalised mentoring","Continuous assessments and exam preparation support"]},{"title":"Professional Football Training","body":"Afternoons are dedicated to elite football development under certified coaches.","items":["Daily sessions on technique, tactics, fitness and teamwork","Official training kits for all students","Matches against professional, semi-pro, academy and amateur teams","Competitive matches and local tournaments","Access to international trials and exposure programmes abroad","National team call-up opportunities at U-15, U-17 and U-20 levels"]},{"title":"Residential Life, Feeding & Support","body":"A conducive, fully residential environment that keeps student-athletes focused and well cared for.","items":["Clean and secure hostel accommodation","Nutritious daily meals for young athletes","Medical insurance coverage and routine health checks","24/7 supervision and pastoral care","Maximum security on campus","Character building and leadership mentoring"]},{"title":"Fitness, Gym & Conditioning","body":"Dedicated fitness and gym sessions that build strength, stamina and agility.","items":["Strength and conditioning workouts","Endurance and agility training","Gym facilities with modern equipment","Personal fitness tracking and progress monitoring","Injury prevention and rehabilitation support"]},{"title":"Pathway to Global Success","body":"Buruj has helped young players reach the next level through professional club trials abroad, scholarships and national team selections.","items":[]}]'::jsonb),
('football-development', 'Football Development', 'Comprehensive season-long development programme', 'Full football season', 'Full Football Season', 4500000, 'season', true, true, 3,
 ARRAY['Full football season training','Technical skill enhancement','Tactical understanding development','Match experience and tournaments','Performance tracking and analytics','Team building and leadership'],
 'The Football Development Programme is designed for dedicated young players who want to take their game to the next level — intensive skill development, tactical understanding, physical conditioning and competitive match experience across a full season.',
 ARRAY[]::text[], NULL,
 'Start your development journey', 'Invest in your football future with professional coaching, modern facilities and competitive opportunities.', 'Register now',
 '[{"title":"Training & Development","body":"Comprehensive training covering every aspect of the game.","items":["Regular structured sessions with licensed coaches","Technical skills (ball control, passing, dribbling, shooting)","Tactical training and positional play","Physical conditioning, strength and fitness","Match preparation and game analysis","Mental conditioning and sports psychology"]},{"title":"Competitive Opportunities","body":"Players gain valuable match experience through:","items":["Local and regional tournaments","Friendly matches against academies and clubs","League participation opportunities","Showcase events for scouts and talent evaluators"]},{"title":"Player Support & Resources","body":"","items":["Official training kits and equipment","Modern training facilities","Performance tracking and progress reports","Injury prevention and basic medical support","Nutritional guidance","Mentorship from experienced coaches and former players"]},{"title":"Pathway Opportunities","body":"Outstanding performers may have access to:","items":["Selection for Buruj Sports Academy Club teams","Recommendations for professional club trials","Consideration for national team youth programmes","Potential international exposure opportunities"]},{"title":"Who Should Join?","body":"This programme is ideal for:","items":["Young players committed to serious football development","Players looking to improve technical and tactical skills","Athletes who want regular competitive match experience","Footballers aspiring to play at higher levels"]}]'::jsonb)
ON CONFLICT (slug) DO NOTHING;